---@class OverseaManageMenuSettingDoubleMenuCell
local OverseaManageMenuSettingDoubleMenuCell = Class('OverseaManageMenuSettingDoubleMenuCell')
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
local KTool = CS.Engine.Lib.KTool
local Image = CS.UnityEngine.UI.Image
local XLuaUtils = CS.Engine.Lib.XLuaUtils
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
function OverseaManageMenuSettingDoubleMenuCell:__init()
    
end

function OverseaManageMenuSettingDoubleMenuCell:__delete()
    
end

function OverseaManageMenuSettingDoubleMenuCell:Awake()
end

-- recipeType  -- recipeId
function OverseaManageMenuSettingDoubleMenuCell:RefreshShow(data)
    self.data = data
    if not isNull(data) then
        ---@type MaidCoffeePlayerComponent
        local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
        local isCafeMax = maidCoffeePlayerComponent:IsToMaxCafeLevel()
        local skillId = isCafeMax and self.data.skill2 or self.data.skill1
        local skillVo = MaidCoffeeUtils.GetMaidCoffeeRecipeSkillVo(skillId)
        local path = MaidCoffeeConstants.RecipeSkillTypeImg[self.data.recipeType]

        CfUtils.FillText(self.SkillDes,skillVo.decr2)
        CfUtils.FillImage(self.ImgIcon,path)

        CfUtils.SetUISwitchImage(self.ImgIcon,1)
        CfUtils.SetUISwitchText(self.SkillDes,1)
    end
end

function OverseaManageMenuSettingDoubleMenuCell:SetIsMatch(data)
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local serverInfo = maidCoffeePlayerComponent:GetRecipeDoJoById(self.data.recipeId)
    local isLocked = true
    if serverInfo then
        isLocked = false
    end
    if not isLocked and not isNull(self.data) then
        local status = data.refId == self.data.recipeId and 2 or 1
        CfUtils.SetUISwitchImage(self.ImgIcon,status)
        CfUtils.SetUISwitchText(self.SkillDes,status)
    else
        CfUtils.SetUISwitchImage(self.ImgIcon,1)
        CfUtils.SetUISwitchText(self.SkillDes,1)
    end
end

function OverseaManageMenuSettingDoubleMenuCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManageMenuSettingDoubleMenuCell